// Each message the program writes: its name, how it is built, how it is read back
struct Case {
    const char* name;
    std::unique_ptr<protocol::Message> (*build)();
    int (*check)(const protocol::Message*);
};

const Case cases[] = {
    { "SecondsTimestampMessage", build_SecondsTimestampMessage, check_SecondsTimestampMessage },
    { "TradingStatusMessage", build_TradingStatusMessage, check_TradingStatusMessage },
    { "ExecutionSummaryMessage", build_ExecutionSummaryMessage, check_ExecutionSummaryMessage },
    { "AddOrderMessage", build_AddOrderMessage, check_AddOrderMessage },
    { "OrderExecutedMessage", build_OrderExecutedMessage, check_OrderExecutedMessage },
    { "OrderExecutedWithPriceMessage", build_OrderExecutedWithPriceMessage, check_OrderExecutedWithPriceMessage },
    { "OrderDeleteMessage", build_OrderDeleteMessage, check_OrderDeleteMessage },
    { "ResetMessage", build_ResetMessage, check_ResetMessage },
    { "CommunicationControlMessage", build_CommunicationControlMessage, check_CommunicationControlMessage },
};

// Each message written into a datagram of its own, encoded by the packet holding it
bool write(const std::string& path) {
    Capture capture(path);
    std::vector<std::byte> bytes;

    for (const auto& each : cases) {
        protocol::UdpPacket packet;
        packet.add(each.build());
        bytes.resize(packet.encoded_size());
        bytes.resize(packet.encode(bytes.data(), bytes.size()));
        capture.write(bytes);
    }

    return capture.good();
}

// Each datagram read back and held to the message written into it; the failures counted
int read(const std::string& path) {
    std::vector<std::pair<std::string, std::int64_t>> sources;
    sources.emplace_back(path, 0);
    packet::PcapIterator captures(sources);

    int failures = 0;
    std::size_t index = 0;

    while (captures.advance() && index < std::size(cases)) {
        const packet::Frame frame(captures.data(), captures.length());
        const auto& each = cases[index++];
        protocol::UdpPacket packet;

        try {
            packet.decode(frame.payload, frame.payload_len);
        } catch (const std::exception& error) {
            std::printf("FAIL %s: %s\n", each.name, error.what());
            ++failures;
            continue;
        }

        if (packet.frames().size() != 1) {
            std::printf("FAIL %s: read back as %zu messages\n", each.name, packet.frames().size());
            ++failures;
            continue;
        }

        const int differences = each.check(packet.frames()[0].message());

        if (differences == 0) {
            std::printf("ok   %s\n", each.name);
        }

        failures += differences;
    }

    if (index != std::size(cases)) {
        std::printf("FAIL: %zu datagrams read of the %zu written\n", index, std::size(cases));
        ++failures;
    }

    return failures;
}

